Let $P$ be a $\phi$-irreducible and aperiodic transition kernel on $(\mathcal{X}, \mathcal{B}(\mathcal{X}))$.
\begin{enumerate}[(i)]
    \item Assume that there exist a probability measure $\nu$ on $\mathcal{X}$, positive constants $\varepsilon, b, c$, a measurable set $\mathcal{C}$, a measurable function $V:\mathcal{X} \to [1,+\infty)$ and $0 < \alpha \leqslant 1$ such that
    \begin{align}
    P(x,\cdot) &\geqslant \varepsilon \mathds{1}_\mathcal{C}(x)\nu(\cdot), 
    \qquad PV \leqslant V - cV^{1-\alpha} + b\mathds{1}_\mathcal{C}. 
    \end{align}
    Then $P$ possesses an invariant probability measure $\pi$ and $\pi(V^{1-\alpha}) < +\infty$.
    \item Assume, in addition, that $c \inf_{\mathcal{C}^c} V^{1-\alpha} \geqslant b$, $\sup_\mathcal{C} V < +\infty$ and $\nu(\mathcal{C}) > 0$. Then there exists a constant $C$ depending on $\sup_\mathcal{C} V$, $\nu(\mathcal{C})$ and $\varepsilon, \alpha, b, c$, such that for any $0 \leqslant \beta \leqslant 1 - \alpha$ and $1 \leqslant \kappa \leqslant \alpha^{-1}(1 - \beta)$,
    \begin{equation}
    (n+1)^{\kappa-1}\|P^n(x,\cdot) - \pi(\cdot)\|_{V^\beta} \leqslant CV^{\beta+\alpha\kappa}(x). 
    \end{equation}
\end{enumerate}
